/* Silly Lionfish 21 by jeremyssocial — https://uiverse.io/jeremyssocial/silly-lionfish-21 */
.fancy-3d-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 15px 30px;
  font-size: 1em;
  font-weight: 700;
  color: #fff;
  background: linear-gradient(45deg, #ff416c, #ff4b2b);
  border: none;
  border-radius: 50px;
  cursor: pointer;
  transition: all 0.6s ease-in-out;
  box-shadow: 0 8px 15px rgba(0, 0, 0, 0.2);
  perspective: 500px;
  transform-style: preserve-3d;
}

.fancy-3d-button::before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: linear-gradient(45deg, #ff9a9e 0%, #fad0c4 100%);
  z-index: -1;
  transition: all 0.6s ease-in-out;
  transform: translateZ(-20px);
  border-radius: 50px;
}

.fancy-3d-button:hover::before {
  transform: translateZ(-40px);
}

.fancy-3d-button:hover {
  transform: rotateX(15deg) rotateY(15deg);
}

.fancy-3d-button:focus {
  outline: none;
  box-shadow: 0 0 0 4px rgba(255, 75, 43, 0.5);
}

.button-icon {
  width: 1.5em;
  height: 1.5em;
  margin-right: 0.5em;
  fill: currentColor;
  transition: transform 0.6s ease-in-out;
  transform: translateZ(10px);
}

.fancy-3d-button:hover .button-icon {
  transform: rotate(360deg) translateZ(10px);
}

.button-text {
  z-index: 2;
  transform: translateZ(10px);
  transition: transform 0.6s ease-in-out;
}

.fancy-3d-button:hover .button-text {
  transform: translateZ(20px);
}
